Heartbeat::Heartbeat() {
  beginString_.set("FIX.4.4");
  bodyLength_.set(999);
}

AbstractField* Heartbeat::msgType() {
  return &beginString_;
}

void Heartbeat::writeUnmapped() {
  valBeg_ = 24;
  valLim_ = 24;
  int bodyBeg = 24;
  valLim_ = testReqID_.write(valLim_);
  int bodyLim = valLim_;
  AbstractMessage::writeUnmapped(bodyLength_, bodyLim - bodyBeg, beginString_, checkSum_);
}

int Heartbeat::writeMapped() {
  int fldLim = AbstractMessage::writeMapped();
  calcAndWriteBodyLengthMapped(bodyLength_, beginString_);
  calcAndWriteCheckSum(checkSum_);
  return fldLim;
}

